type Row = Record<string, unknown>;

function str(value: unknown): string | undefined {
  return value === null || value === undefined ? undefined : String(value);
}

function date(value: unknown): Date | undefined {
  return value === null || value === undefined ? undefined : new Date(String(value));
}

function provenance(raw: unknown): KnowledgeProvenance {
  return JSON.parse(String(raw)) as KnowledgeProvenance;
}

function toPage(row: Row): KnowledgePage {
  return {
    id: String(row.id),
    scopeId: String(row.scopeId),
    parentId: str(row.parentId) ?? null,
    isScope: Number(row.isScope) === 1,
    ...(row.address !== null && row.address !== undefined ? { address: String(row.address) } : {}),
    ...(row.declaration !== null && row.declaration !== undefined ? { declaration: String(row.declaration) } : {}),
    ...(row.key !== null && row.key !== undefined ? { key: String(row.key) } : {}),
    position: String(row.position),
    name: String(row.name),
    ...(row.description !== null && row.description !== undefined ? { description: String(row.description) } : {}),
    ...(row.body !== null && row.body !== undefined ? { body: String(row.body) } : {}),
    version: Number(row.version),
    ...(row.mergedInto !== null && row.mergedInto !== undefined ? { mergedInto: String(row.mergedInto) } : {}),
    createdBy: provenance(row.createdBy),
    updatedBy: provenance(row.updatedBy),
    createdAt: new Date(String(row.createdAt)),
    updatedAt: new Date(String(row.updatedAt)),
    ...(row.deletedAt ? { deletedAt: new Date(String(row.deletedAt)) } : {}),
    ...(row.deletedBy ? { deletedBy: String(row.deletedBy) } : {}),
  };
}

function toNote(row: Row, stamps: string[], mentions: string[]): KnowledgeNote {
  const when = date(row.when);
  return {
    id: String(row.id),
    pageId: String(row.pageId),
    text: String(row.text),
    ...(when ? { when } : {}),
    stampScopeIds: stamps,
    mentions,
    provenance: provenance(row.provenance),
    version: Number(row.version),
    createdAt: new Date(String(row.createdAt)),
    updatedAt: new Date(String(row.updatedAt)),
    ...(row.deletedAt ? { deletedAt: new Date(String(row.deletedAt)) } : {}),
    ...(row.deletedBy ? { deletedBy: String(row.deletedBy) } : {}),
  };
}

function toPin(row: Row): KnowledgePin {
  return {
    id: String(row.id),
    pageId: String(row.pageId),
    kind: String(row.kind) as KnowledgePinKind,
    ...(row.depth !== null && row.depth !== undefined ? { depth: Number(row.depth) } : {}),
    audience: JSON.parse(String(row.audience)) as string[],
    createdBy: String(row.createdBy),
    createdAt: new Date(String(row.createdAt)),
    updatedAt: new Date(String(row.updatedAt)),
  };
}

function toListedPin(row: Row): KnowledgeListedPin {
  return { ...toPin(row), pageName: String(row.pageName) };
}

function limitOf(limit: number | undefined, max: number): number {
  return Math.max(1, Math.min(limit ?? max, max));
}

function encodeCursor(value: unknown[]): string {
  return Buffer.from(JSON.stringify(value)).toString('base64url');
}

function decodeCursor(cursor: string | undefined, length: number): string[] | undefined {
  if (cursor === undefined) return undefined;
  try {
    const parsed = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8')) as unknown;
    if (Array.isArray(parsed) && parsed.length === length && parsed.every(item => typeof item === 'string')) {
      return parsed as string[];
    }
  } catch {
    // fall through
  }
  throw new Error('Invalid Knowledge cursor');
}

function escapeLike(value: string): string {
  return value.replace(/[=%_]/g, match => `=${match}`);
}

interface Fragment {
  sql: string;
  args: InValue[];
}

/**
 * A string above every string that starts with `prefix`, comparing by code point (which is also
 * UTF-8 byte order, so it matches SQLite's BINARY collation). `column >= prefix AND column < bound`
 * is an exact, case-sensitive prefix match that an index range scan can serve, where
 * `substr(column, 1, length(prefix)) = prefix` cannot. When the last code point cannot be raised
 * (an empty prefix, or one made only of U+10FFFF), the bound is the prefix plus more U+10FFFF than
 * any stored column can hold.
 */
function prefixUpperBound(prefix: string): string {
  const points = Array.from(prefix);
  while (points.length > 0) {
    const last = points.pop()!.codePointAt(0)!;
    if (last < 0x10ffff) {
      const next = last === 0xd7ff ? 0xe000 : last + 1;
      return points.join('') + String.fromCodePoint(next);
    }
  }
  return prefix + '\u{10FFFF}'.repeat(4096);
}

/** `column` starts with `prefix`, as an index-friendly range. */
function prefixRange(column: string, prefix: string): Fragment {
  return { sql: `(${column} >= ? AND ${column} < ?)`, args: [prefix, prefixUpperBound(prefix)] };
}

/**
 * The readable scope page ids as a subquery. The caller's addresses, prefixes and children go in as
 * JSON arrays so a large read scope never hits a bind-parameter limit. Each kind is its own index
 * lookup (address equality, address range for a prefix, `(declaration, parentId)` for children),
 * unioned, so the cost follows the caller's reach rather than the number of scopes in the store.
 */
function readableScopes(read: KnowledgeReadScope): Fragment {
  if (read === 'all') return { sql: `SELECT id FROM "${T.pages}" WHERE isScope = 1`, args: [] };
  const parts: string[] = [];
  const args: InValue[] = [];
  if (read.addresses.length > 0) {
    parts.push(`SELECT id FROM "${T.pages}" WHERE isScope = 1 AND address IN (SELECT value FROM json_each(?))`);
    args.push(JSON.stringify(read.addresses));
  }
  if (read.prefixes.length > 0) {
    parts.push(
      `SELECT sp.id FROM json_each(?) j CROSS JOIN "${T.pages}" sp ON sp.isScope = 1 AND sp.address >= json_extract(j.value, '$.lo') AND sp.address < json_extract(j.value, '$.hi') AND +sp.declaration = json_extract(j.value, '$.declaration')`,
    );
    args.push(
      JSON.stringify(
        read.prefixes.map(entry => ({
          declaration: entry.declaration,
          lo: entry.prefix,
          hi: prefixUpperBound(entry.prefix),
        })),
      ),
    );
  }
  if (read.children.length > 0) {
    parts.push(
      `SELECT sp.id FROM json_each(?) j CROSS JOIN "${T.pages}" sp ON sp.isScope = 1 AND sp.declaration = json_extract(j.value, '$.declaration') AND sp.parentId IS json_extract(j.value, '$.parentId')`,
    );
    args.push(JSON.stringify(read.children));
  }
  if (parts.length === 0) return { sql: `SELECT id FROM "${T.pages}" WHERE 0`, args: [] };
  return { sql: parts.join(' UNION '), args };
}

/** `alias.scopeId` is readable. */
function pageReadable(alias: string, read: KnowledgeReadScope): Fragment {
  const scopes = readableScopes(read);
  return { sql: `${alias}.scopeId IN (${scopes.sql})`, args: scopes.args };
}

/**
 * Note `alias` is visible: its page's scope is readable, a stamp is readable, and every resolved
 * mention's page sits in a readable scope.
 */
function noteReadable(alias: string, read: KnowledgeReadScope): Fragment {
  const scopes = readableScopes(read);
  return {
    sql: `EXISTS (SELECT 1 FROM "${T.pages}" vp WHERE vp.id = ${alias}.pageId AND vp.scopeId IN (${scopes.sql}))
      AND EXISTS (SELECT 1 FROM "${T.stamps}" vs WHERE vs.noteId = ${alias}.id AND vs.scopeId IN (${scopes.sql}))
      AND NOT EXISTS (SELECT 1 FROM "${T.mentions}" vm JOIN "${T.pages}" vmp ON vmp.id = vm.pageId WHERE vm.noteId = ${alias}.id AND vmp.scopeId NOT IN (${scopes.sql}))`,
    args: [...scopes.args, ...scopes.args, ...scopes.args],
  };
}

function jsonList(values: string[]): string {
  return JSON.stringify(values);
}

export class LibSQLKnowledgePages implements KnowledgePageStore {
  readonly #read: PageExecutor;
  readonly #transaction: PageTransaction;

  constructor(config: { read: PageExecutor; transaction: PageTransaction }) {
    this.#read = config.read;
    this.#transaction = config.transaction;
  }

  /** Deletes every row from the page tables (scopes, pages, notes, pins, activity, links). */
  async clearAll(): Promise<void> {
    await this.#transaction(async tx => {
      for (const table of [T.links, T.activity, T.pinAudiences, T.pins, T.mentions, T.stamps, T.notes, T.pages]) {
        await tx.execute({ sql: `DELETE FROM ${table}`, args: [] });
      }
    });
  }

  async #query(executor: PageExecutor, sql: string, args: InValue[] = []): Promise<Row[]> {
    const result = await executor.execute({ sql, args });
    return result.rows as unknown as Row[];
  }

  async #pageRow(executor: PageExecutor, id: string): Promise<Row | undefined> {
    return (await this.#query(executor, `SELECT * FROM "${T.pages}" WHERE id = ?`, [id]))[0];
  }

  async #livePage(executor: PageExecutor, id: string): Promise<Row> {
    const row = await this.#pageRow(executor, id);
    if (!row || row.deletedAt) throw new KnowledgeNotFoundError('page', id);
    return row;
  }

  async #logActivity(
    tx: PageExecutor,
    action: KnowledgePageActivityAction,
    event: { scopeId: string; pageId: string; noteId?: string; provenance: KnowledgeProvenance },
    now: string,
  ): Promise<void> {
    await tx.execute({
      sql: `INSERT INTO "${T.activity}" (id, action, scopeId, pageId, noteId, provenance, createdAt) VALUES (?, ?, ?, ?, ?, ?, ?)`,
      args: [
        createKnowledgeUlid(),
        action,
        event.scopeId,
        event.pageId,
        event.noteId ?? null,
        JSON.stringify(event.provenance),
        now,
      ],
    });
  }

  async #lastPosition(tx: PageExecutor, parentId: string | null, scopesOnly: boolean): Promise<string | undefined> {
    const rows = await this.#query(
      tx,
      `SELECT position FROM "${T.pages}" WHERE parentId IS ? AND isScope = ? AND deletedAt IS NULL ORDER BY position DESC, id DESC LIMIT 1`,
      [parentId, scopesOnly ? 1 : 0],
    );
    return rows[0] ? String(rows[0].position) : undefined;
  }

  // Scopes

  async materializeScope(input: MaterializeKnowledgeScopeInput): Promise<MaterializeKnowledgeScopeResult> {
    const core = await loadPagesCore();
    await assertKnowledgePageDescriptionWithinBound(input.description);
    return this.#transaction(async tx => {
      const now = new Date().toISOString();
      const ensureScope = async (
        spec: { address: string; declaration: string; name: string; description?: string },
        parentId: string | null,
      ) => {
        await assertKnowledgePageDescriptionWithinBound(spec.description);
        const existing = (
          await this.#query(tx, `SELECT * FROM "${T.pages}" WHERE isScope = 1 AND address = ?`, [spec.address])
        )[0];
        if (existing) return { row: existing, created: false };
        if (parentId !== null) await this.#livePage(tx, parentId);
        const id = createKnowledgeUlid();
        const position = core.knowledgePositionBetween(await this.#lastPosition(tx, parentId, true));
        const who = JSON.stringify(input.provenance);
        await tx.execute({
          sql: `INSERT INTO "${T.pages}" (id, scopeId, isScope, address, declaration, parentId, position, path, depth, name, canonicalName, description, version, createdBy, updatedBy, createdAt, updatedAt) VALUES (?, ?, 1, ?, ?, ?, ?, ?, 0, ?, ?, ?, 1, ?, ?, ?, ?)`,
          args: [
            id,
            id,
            spec.address,
            spec.declaration,
            parentId,
            position,
            `/${id}/`,
            spec.name,
            core.canonicalKnowledgeName(spec.name),
            spec.description ?? null,
            who,
            who,
            now,
            now,
          ],
        });
        await this.#logActivity(tx, 'scope-created', { scopeId: id, pageId: id, provenance: input.provenance }, now);
        return { row: (await this.#pageRow(tx, id))!, created: true };
      };

      const ensured = await ensureScope(input, input.parentId ?? null);
      let row = ensured.row;
      const created = ensured.created;
      const scopeId = String(row.id);
      if (!created && input.parentId != null && str(row.parentId) === undefined) {
        // An unlinked scope takes its first parent; the conditional UPDATE keeps the first writer's link.
        await this.#livePage(tx, input.parentId);
        if (input.parentId === scopeId) throw new Error(`Scope ${scopeId} cannot be its own parent`);
        let ancestor: string | undefined = input.parentId;
        while (ancestor) {
          const up = (await this.#pageRow(tx, ancestor))!;
          if (String(up.id) === scopeId) throw new Error(`Scope ${scopeId} cannot be linked under its own descendant`);
          ancestor = str(up.parentId);
        }
        await tx.execute({
          sql: `UPDATE "${T.pages}" SET parentId = ?, position = ?, version = version + 1, updatedAt = ? WHERE id = ? AND parentId IS NULL`,
          args: [
            input.parentId,
            core.knowledgePositionBetween(await this.#lastPosition(tx, input.parentId, true)),
            now,
            scopeId,
          ],
        });
        row = (await this.#pageRow(tx, scopeId))!;
      }
      let parentConflict: MaterializeKnowledgeScopeResult['parentConflict'];
      if (!created && input.parentId !== undefined && (str(row.parentId) ?? null) !== input.parentId) {
        parentConflict = { existingParentId: str(row.parentId) ?? null, requestedParentId: input.parentId };
      }
      for (const child of input.children ?? []) await ensureScope(child, scopeId);
      const ensureTemplates = async (
        templates: NonNullable<MaterializeKnowledgeScopeInput['pages']>,
        parentId: string,
      ): Promise<void> => {
        for (const template of templates) {
          const problem = knowledgePageKeyProblem(template.key);
          if (problem) throw new Error(problem);
          const existing = (
            await this.#query(
              tx,
              `SELECT id FROM "${T.pages}" WHERE parentId = ? AND isScope = 0 AND key = ? AND deletedAt IS NULL`,
              [parentId, template.key],
            )
          )[0];
          const id = existing
            ? String(existing.id)
            : (
                await this.#insertPage(tx, {
                  parentId,
                  key: template.key,
                  name: template.name,
                  description: template.description,
                  provenance: input.provenance,
                })
              ).id;
          if (template.pages?.length) await ensureTemplates(template.pages, id);
        }
      };
      await ensureTemplates(input.pages ?? [], scopeId);
      return {
        scope: toPage((await this.#pageRow(tx, scopeId))!),
        created,
        ...(parentConflict ? { parentConflict } : {}),
      };
    });
  }

  async listScopeDeclarations(): Promise<KnowledgeScopeDeclarationCount[]> {
    const rows = await this.#query(
      this.#read,
      `SELECT declaration, COUNT(*) AS scopes FROM "${T.pages}" WHERE isScope = 1 AND declaration IS NOT NULL GROUP BY declaration ORDER BY declaration`,
    );
    return rows.map(row => ({ declaration: String(row.declaration), scopes: Number(row.scopes) }));
  }

  async renameScopeDeclaration(input: {
    from: string;
    to: string;
    check: (scopes: KnowledgeScopeDeclarationRename[]) => void;
  }): Promise<number> {
    return this.#transaction(async tx => {
      const within = prefixRange('declaration', `${input.from}/`);
      const rows = await this.#query(
        tx,
        `SELECT id, address, declaration FROM "${T.pages}" WHERE isScope = 1 AND (declaration = ? OR ${within.sql})`,
        [input.from, ...within.args],
      );
      // Collations may pad or fold; keep only exact, case-sensitive matches.
      const affected = rows
        .map(row => ({ id: String(row.id), address: String(row.address), from: String(row.declaration) }))
        .filter(row => row.from === input.from || row.from.startsWith(`${input.from}/`))
        .map(row => ({ ...row, to: input.to + row.from.slice(input.from.length) }));
      input.check(affected.map(({ address, from, to }) => ({ address, from, to })));
      for (const row of affected) {
        await tx.execute({ sql: `UPDATE "${T.pages}" SET declaration = ? WHERE id = ?`, args: [row.to, row.id] });
      }
      return affected.length;
    });
  }

  async getScopesByAddress(addresses: string[]): Promise<KnowledgePage[]> {
    if (addresses.length === 0) return [];
    const rows = await this.#query(
      this.#read,
      `SELECT * FROM "${T.pages}" WHERE isScope = 1 AND address IN (SELECT value FROM json_each(?))`,
      [jsonList(addresses)],
    );
    return rows.map(toPage);
  }

  async listChildScopes(input: {
    parentId: string | null;
    read?: KnowledgeReadScope;
    cursor?: string;
    limit?: number;
  }): Promise<KnowledgePageListOutput> {
    const core = await loadPagesCore();
    const limit = limitOf(input.limit, core.MAX_KNOWLEDGE_PAGE_LIST_LIMIT);
    const cursor = decodeCursor(input.cursor, 2);
    const args: InValue[] = [input.parentId];
    let filter = '';
    if (input.read) {
      const readable = readableScopes(input.read);
      filter = ` AND id IN (${readable.sql})`;
      args.push(...readable.args);
    }
    let after = '';
    if (cursor) {
      after = ` AND (position > ? OR (position = ? AND id > ?))`;
      args.push(cursor[0]!, cursor[0]!, cursor[1]!);
    }
    args.push(limit + 1);
    const rows = await this.#query(
      this.#read,
      `SELECT * FROM "${T.pages}" WHERE isScope = 1 AND parentId IS ?${filter}${after} ORDER BY position, id LIMIT ?`,
      args,
    );
    return this.#pageOutput(rows, limit, row => [String(row.position), String(row.id)]);
  }

  #pageOutput(rows: Row[], limit: number, cursorOf: (row: Row) => string[]): KnowledgePageListOutput {
    const page = rows.slice(0, limit);
    return {
      pages: page.map(toPage),
      ...(rows.length > limit ? { nextCursor: encodeCursor(cursorOf(page[page.length - 1]!)) } : {}),
    };
  }

  // Pages

  async getPage(input: { id: string; read: KnowledgeReadScope }): Promise<KnowledgePage | null> {
    const readable = pageReadable('p', input.read);
    const rows = await this.#query(this.#read, `SELECT p.* FROM "${T.pages}" p WHERE p.id = ? AND ${readable.sql}`, [
      input.id,
      ...readable.args,
    ]);
    return rows[0] ? toPage(rows[0]) : null;
  }

  async getPages(input: { ids: string[]; read: KnowledgeReadScope }): Promise<KnowledgePage[]> {
    const ids = [...new Set(input.ids)];
    if (ids.length === 0) return [];
    const readable = pageReadable('p', input.read);
    const rows = await this.#query(
      this.#read,
      `SELECT p.* FROM "${T.pages}" p WHERE p.deletedAt IS NULL AND p.id IN (SELECT value FROM json_each(?)) AND ${readable.sql}`,
      [jsonList(ids), ...readable.args],
    );
    return rows.map(toPage);
  }

  async getPageByPath(input: {
    scopeId: string;
    path: string[];
    read: KnowledgeReadScope;
  }): Promise<KnowledgePage | null> {
    const readable = pageReadable('p', input.read);
    let parentId = input.scopeId;
    let row: Row | undefined;
    for (const key of input.path) {
      row = (
        await this.#query(
          this.#read,
          `SELECT p.* FROM "${T.pages}" p WHERE p.parentId = ? AND p.isScope = 0 AND p.key = ? AND p.deletedAt IS NULL AND ${readable.sql}`,
          [parentId, key, ...readable.args],
        )
      )[0];
      if (!row) return null;
      parentId = String(row.id);
    }
    return row ? toPage(row) : null;
  }

  async findPagesByName(input: {
    name: string;
    read: KnowledgeReadScope;
    scopeId?: string;
    limit?: number;
  }): Promise<KnowledgePage[]> {
    const core = await loadPagesCore();
    const readable = pageReadable('p', input.read);
    const args: InValue[] = [core.canonicalKnowledgeName(input.name), ...readable.args];
    let scope = '';
    if (input.scopeId !== undefined) {
      scope = ` AND p.scopeId = ?`;
      args.push(input.scopeId);
    }
    args.push(limitOf(input.limit, core.MAX_KNOWLEDGE_PAGE_LIST_LIMIT));
    const rows = await this.#query(
      this.#read,
      `SELECT p.* FROM "${T.pages}" p WHERE p.canonicalName = ? AND p.deletedAt IS NULL AND ${readable.sql}${scope} ORDER BY p.createdAt DESC, p.id DESC LIMIT ?`,
      args,
    );
    return rows.map(toPage);
  }

  async listChildPages(input: {
    parentId: string;
    read: KnowledgeReadScope;
    cursor?: string;
    limit?: number;
  }): Promise<KnowledgePageListOutput> {
    const core = await loadPagesCore();
    const limit = limitOf(input.limit, core.MAX_KNOWLEDGE_PAGE_LIST_LIMIT);
    const cursor = decodeCursor(input.cursor, 2);
    const readable = pageReadable('p', input.read);
    const args: InValue[] = [input.parentId, ...readable.args];
    let after = '';
    if (cursor) {
      after = ` AND (p.position > ? OR (p.position = ? AND p.id > ?))`;
      args.push(cursor[0]!, cursor[0]!, cursor[1]!);
    }
    args.push(limit + 1);
    const rows = await this.#query(
      this.#read,
      `SELECT p.* FROM "${T.pages}" p WHERE p.parentId = ? AND p.isScope = 0 AND p.deletedAt IS NULL AND ${readable.sql}${after} ORDER BY p.position, p.id LIMIT ?`,
      args,
    );
    return this.#pageOutput(rows, limit, row => [String(row.position), String(row.id)]);
  }

  async listPages(input: {
    read: KnowledgeReadScope;
    scopeId?: string;
    namePrefix?: string;
    cursor?: string;
    limit?: number;
  }): Promise<KnowledgePageListOutput> {
    const core = await loadPagesCore();
    const limit = limitOf(input.limit, core.MAX_KNOWLEDGE_PAGE_LIST_LIMIT);
    const cursor = decodeCursor(input.cursor, 2);
    const readable = pageReadable('p', input.read);
    const args: InValue[] = [...readable.args];
    let filters = '';
    if (input.scopeId !== undefined) {
      filters += ` AND p.scopeId = ?`;
      args.push(input.scopeId);
    }
    if (input.namePrefix) {
      const prefix = core.canonicalKnowledgeName(input.namePrefix);
      filters += ` AND substr(p.canonicalName, 1, length(?)) = ?`;
      args.push(prefix, prefix);
    }
    if (cursor) {
      filters += ` AND (p.name > ? OR (p.name = ? AND p.id > ?))`;
      args.push(cursor[0]!, cursor[0]!, cursor[1]!);
    }
    args.push(limit + 1);
    const rows = await this.#query(
      this.#read,
      `SELECT p.* FROM "${T.pages}" p WHERE p.isScope = 0 AND p.deletedAt IS NULL AND ${readable.sql}${filters} ORDER BY p.name, p.id LIMIT ?`,
      args,
    );
    return this.#pageOutput(rows, limit, row => [String(row.name), String(row.id)]);
  }

  async #insertPage(tx: PageExecutor, input: CreateKnowledgePageInput): Promise<KnowledgePage> {
    const core = await loadPagesCore();
    await assertKnowledgePageDescriptionWithinBound(input.description);
    const parent = await this.#livePage(tx, input.parentId);
    const isScopeParent = Number(parent.isScope) === 1;
    const scopeId = isScopeParent ? String(parent.id) : String(parent.scopeId);
    const depth = isScopeParent ? 1 : Number(parent.depth) + 1;
    if (depth > core.MAX_KNOWLEDGE_PAGE_DEPTH) throw new core.KnowledgePageDepthError(input.parentId);
    const id = input.id ?? createKnowledgeUlid();
    if (await this.#pageRow(tx, id)) throw new KnowledgeConflictError(id);
    if (input.key !== undefined) {
      const problem = knowledgePageKeyProblem(input.key);
      if (problem) throw new Error(problem);
      const clash = await this.#query(
        tx,
        `SELECT id FROM "${T.pages}" WHERE parentId = ? AND isScope = 0 AND key = ? AND deletedAt IS NULL`,
        [String(parent.id), input.key],
      );
      if (clash.length > 0) throw new core.KnowledgePageKeyConflictError(input.key, String(parent.id));
    }
    const position =
      input.position ?? core.knowledgePositionBetween(await this.#lastPosition(tx, String(parent.id), false));
    const now = new Date().toISOString();
    const who = JSON.stringify(input.provenance);
    await tx.execute({
      sql: `INSERT INTO "${T.pages}" (id, scopeId, isScope, key, parentId, position, path, depth, name, canonicalName, description, body, version, createdBy, updatedBy, createdAt, updatedAt) VALUES (?, ?, 0, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?, ?)`,
      args: [
        id,
        scopeId,
        input.key ?? null,
        String(parent.id),
        position,
        `${String(parent.path)}${id}/`,
        depth,
        input.name,
        core.canonicalKnowledgeName(input.name),
        input.description || null,
        input.body ?? null,
        who,
        who,
        now,
        now,
      ],
    });
    await this.#logActivity(tx, 'page-created', { scopeId, pageId: id, provenance: input.provenance }, now);
    return toPage((await this.#pageRow(tx, id))!);
  }

  async createPage(input: CreateKnowledgePageInput): Promise<KnowledgePage> {
    await assertKnowledgePageDescriptionWithinBound(input.description);
    return this.#transaction(tx => this.#insertPage(tx, input));
  }

  async updatePage(input: UpdateKnowledgePageInput): Promise<KnowledgePage> {
    const core = await loadPagesCore();
    await assertKnowledgePageDescriptionWithinBound(input.description);
    return this.#transaction(async tx => {
      const row = await this.#livePage(tx, input.id);
      if (Number(row.version) !== input.expectedVersion) throw new KnowledgeConflictError(input.id);
      const now = new Date().toISOString();
      const name = input.name ?? String(row.name);
      const description = input.description === undefined ? (row.description ?? null) : input.description || null;
      const body = input.body === undefined ? (row.body ?? null) : input.body;
      await tx.execute({
        sql: `UPDATE "${T.pages}" SET name = ?, canonicalName = ?, description = ?, body = ?, version = version + 1, updatedBy = ?, updatedAt = ? WHERE id = ?`,
        args: [
          name,
          core.canonicalKnowledgeName(name),
          description as InValue,
          body as InValue,
          JSON.stringify(input.provenance),
          now,
          input.id,
        ],
      });
      await this.#logActivity(
        tx,
        'page-updated',
        { scopeId: String(row.scopeId), pageId: input.id, provenance: input.provenance },
        now,
      );
      return toPage((await this.#pageRow(tx, input.id))!);
    });
  }

  /**
   * Rehomes `root` (and its subtree) under `parent`: new path prefix, scope and depth in one go.
   * Throws when the subtree is too large, too deep, or the root's key clashes with a live child of `parent`.
   */
  async #rehome(
    tx: PageExecutor,
    root: Row,
    parent: Row,
    options: { position?: string; countLimitId: string; skipRootCount?: boolean },
  ): Promise<{ moved: number; scopeId: string }> {
    const core = await loadPagesCore();
    const isScopeParent = Number(parent.isScope) === 1;
    const newScopeId = isScopeParent ? String(parent.id) : String(parent.scopeId);
    const newDepth = isScopeParent ? 1 : Number(parent.depth) + 1;
    const oldPath = String(root.path);
    const within = prefixRange('path', oldPath);
    const subtree = await this.#query(
      tx,
      `SELECT id, key, depth, deletedAt FROM "${T.pages}" WHERE ${within.sql}`,
      within.args,
    );
    const live = subtree.filter(row => !row.deletedAt);
    if (live.length > core.MAX_KNOWLEDGE_MOVE_PAGES)
      throw new core.KnowledgeMoveTooLargeError(options.countLimitId, live.length);
    const shift = newDepth - Number(root.depth);
    const deepest = Math.max(...live.map(row => Number(row.depth)));
    if (deepest + shift > core.MAX_KNOWLEDGE_PAGE_DEPTH) throw new core.KnowledgePageDepthError(String(root.id));
    if (!root.deletedAt && root.key !== null) {
      const clash = await this.#query(
        tx,
        `SELECT id FROM "${T.pages}" WHERE parentId = ? AND isScope = 0 AND key = ? AND deletedAt IS NULL AND id <> ?`,
        [String(parent.id), String(root.key), String(root.id)],
      );
      if (clash.length > 0) throw new core.KnowledgePageKeyConflictError(String(root.key), String(parent.id));
    }
    const newPath = `${String(parent.path)}${String(root.id)}/`;
    const position =
      options.position ?? core.knowledgePositionBetween(await this.#lastPosition(tx, String(parent.id), false));
    await tx.execute({
      sql: `UPDATE "${T.pages}" SET path = ? || substr(path, length(?) + 1), depth = depth + ?, scopeId = ? WHERE ${within.sql}`,
      args: [newPath, oldPath, shift, newScopeId, ...within.args],
    });
    await tx.execute({
      sql: `UPDATE "${T.pages}" SET parentId = ?, position = ? WHERE id = ?`,
      args: [String(parent.id), position, String(root.id)],
    });
    return { moved: live.length, scopeId: newScopeId };
  }

  movePage(input: MoveKnowledgePageInput): Promise<KnowledgePage> {
    return this.#transaction(async tx => {
      const row = await this.#livePage(tx, input.id);
      if (Number(row.isScope) === 1) throw new Error(`Cannot move ${input.id}: it is a scope page`);
      if (Number(row.version) !== input.expectedVersion) throw new KnowledgeConflictError(input.id);
      const parent = await this.#livePage(tx, input.parentId);
      const path = String(row.path);
      if (String(parent.id) === input.id || String(parent.path).startsWith(path)) {
        throw new Error(`Cannot move ${input.id} into its own subtree`);
      }
      const now = new Date().toISOString();
      const { scopeId } = await this.#rehome(tx, row, parent, {
        position: input.position,
        countLimitId: input.id,
      });
      await tx.execute({
        sql: `UPDATE "${T.pages}" SET version = version + 1, updatedBy = ?, updatedAt = ? WHERE id = ?`,
        args: [JSON.stringify(input.provenance), now, input.id],
      });
      await this.#logActivity(tx, 'page-moved', { scopeId, pageId: input.id, provenance: input.provenance }, now);
      return toPage((await this.#pageRow(tx, input.id))!);
    });
  }

  async mergePages(input: MergeKnowledgePagesInput): Promise<KnowledgePage> {
    const core = await loadPagesCore();
    return this.#transaction(async tx => {
      const source = await this.#livePage(tx, input.sourceId);
      const target = await this.#livePage(tx, input.targetId);
      if (Number(source.isScope) === 1 || Number(target.isScope) === 1) {
        throw new Error('Cannot merge a scope page: merging applies to non-scope pages only');
      }
      if (Number(source.version) !== input.sourceVersion) throw new KnowledgeConflictError(input.sourceId);
      const sourcePath = String(source.path);
      if (input.sourceId === input.targetId || String(target.path).startsWith(sourcePath)) {
        throw new Error(
          `Page ${input.targetId} is inside page ${input.sourceId}; it cannot be the merge target (subtree)`,
        );
      }
      const within = prefixRange('path', sourcePath);
      const carried = await this.#query(
        tx,
        `SELECT COUNT(*) AS n FROM "${T.pages}" WHERE ${within.sql} AND id <> ? AND deletedAt IS NULL`,
        [...within.args, input.sourceId],
      );
      if (Number(carried[0]!.n) > core.MAX_KNOWLEDGE_MOVE_PAGES) {
        throw new core.KnowledgeMoveTooLargeError(input.sourceId, Number(carried[0]!.n));
      }
      const now = new Date().toISOString();
      // The source goes first so its own key never clashes with a child that takes the same parent.
      await tx.execute({
        sql: `UPDATE "${T.pages}" SET deletedAt = ?, deletedBy = ?, mergedInto = ?, scopeId = ?, version = version + 1, updatedBy = ?, updatedAt = ? WHERE id = ?`,
        args: [
          now,
          input.provenance.author,
          input.targetId,
          String(target.scopeId),
          JSON.stringify(input.provenance),
          now,
          input.sourceId,
        ],
      });
      const children = await this.#query(tx, `SELECT * FROM "${T.pages}" WHERE parentId = ? AND isScope = 0`, [
        input.sourceId,
      ]);
      for (const child of children) {
        await this.#rehome(tx, child, target, {
          position: String(child.position),
          countLimitId: input.sourceId,
        });
      }
      await tx.execute({
        sql: `UPDATE "${T.notes}" SET pageId = ? WHERE pageId = ?`,
        args: [input.targetId, input.sourceId],
      });
      await tx.execute({
        sql: `UPDATE OR IGNORE "${T.mentions}" SET pageId = ? WHERE pageId = ?`,
        args: [input.targetId, input.sourceId],
      });
      await tx.execute({ sql: `DELETE FROM "${T.mentions}" WHERE pageId = ?`, args: [input.sourceId] });
      const pins = await this.#query(tx, `SELECT * FROM "${T.pins}" WHERE pageId IN (?, ?)`, [
        input.sourceId,
        input.targetId,
      ]);
      for (const sourcePin of pins.filter(pin => String(pin.pageId) === input.sourceId)) {
        const targetPin = pins.find(pin => String(pin.pageId) === input.targetId && pin.kind === sourcePin.kind);
        const audience = JSON.parse(String(sourcePin.audience)) as string[];
        if (targetPin) {
          const merged = [...new Set([...(JSON.parse(String(targetPin.audience)) as string[]), ...audience])];
          await tx.execute({
            sql: `UPDATE "${T.pins}" SET audience = ?, updatedAt = ? WHERE id = ?`,
            args: [JSON.stringify(merged), now, String(targetPin.id)],
          });
          await this.#indexAudience(tx, String(targetPin.id), merged);
          await this.#indexAudience(tx, String(sourcePin.id), []);
          await tx.execute({ sql: `DELETE FROM "${T.pins}" WHERE id = ?`, args: [String(sourcePin.id)] });
        } else {
          await tx.execute({
            sql: `UPDATE "${T.pins}" SET pageId = ?, updatedAt = ? WHERE id = ?`,
            args: [input.targetId, now, String(sourcePin.id)],
          });
        }
      }
      await this.#logActivity(
        tx,
        'page-merged',
        { scopeId: String(target.scopeId), pageId: input.sourceId, provenance: input.provenance },
        now,
      );
      return toPage((await this.#pageRow(tx, input.targetId))!);
    });
  }

  async deletePage(input: { id: string; expectedVersion: number; deletedBy: string }): Promise<KnowledgePage> {
    const core = await loadPagesCore();
    return this.#transaction(async tx => {
      const row = await this.#livePage(tx, input.id);
      if (Number(row.isScope) === 1) throw new Error(`Cannot delete ${input.id}: it is a scope page`);
      if (Number(row.version) !== input.expectedVersion) throw new KnowledgeConflictError(input.id);
      const children = await this.#query(
        tx,
        `SELECT 1 FROM "${T.pages}" WHERE parentId = ? AND deletedAt IS NULL LIMIT 1`,
        [input.id],
      );
      if (children.length > 0) throw new core.KnowledgePageHasChildrenError(input.id);
      const now = new Date().toISOString();
      await tx.execute({
        sql: `UPDATE "${T.pages}" SET deletedAt = ?, deletedBy = ?, version = version + 1, updatedBy = ?, updatedAt = ? WHERE id = ?`,
        args: [now, input.deletedBy, JSON.stringify({ author: input.deletedBy }), now, input.id],
      });
      await tx.execute({
        sql: `DELETE FROM "${T.pinAudiences}" WHERE pinId IN (SELECT id FROM "${T.pins}" WHERE pageId = ?)`,
        args: [input.id],
      });
      await tx.execute({ sql: `DELETE FROM "${T.pins}" WHERE pageId = ?`, args: [input.id] });
      await this.#logActivity(
        tx,
        'page-deleted',
        { scopeId: String(row.scopeId), pageId: input.id, provenance: { author: input.deletedBy } },
        now,
      );
      return toPage((await this.#pageRow(tx, input.id))!);
    });
  }

  // Notes

  async #hydrateNotes(executor: PageExecutor, rows: Row[]): Promise<KnowledgeNote[]> {
    if (rows.length === 0) return [];
    const ids = jsonList(rows.map(row => String(row.id)));
    const stamps = await this.#query(
      executor,
      `SELECT noteId, scopeId FROM "${T.stamps}" WHERE noteId IN (SELECT value FROM json_each(?)) ORDER BY scopeId`,
      [ids],
    );
    const mentions = await this.#query(
      executor,
      `SELECT noteId, pageId FROM "${T.mentions}" WHERE noteId IN (SELECT value FROM json_each(?)) ORDER BY pageId`,
      [ids],
    );
    return rows.map(row =>
      toNote(
        row,
        stamps.filter(stamp => String(stamp.noteId) === String(row.id)).map(stamp => String(stamp.scopeId)),
        mentions.filter(mention => String(mention.noteId) === String(row.id)).map(mention => String(mention.pageId)),
      ),
    );
  }

  async #noteById(executor: PageExecutor, id: string): Promise<KnowledgeNote | null> {
    const rows = await this.#query(executor, `SELECT * FROM "${T.notes}" WHERE id = ?`, [id]);
    return (await this.#hydrateNotes(executor, rows))[0] ?? null;
  }

  async getNote(input: {
    id: string;
    read: KnowledgeReadScope;
    includeDeleted?: boolean;
  }): Promise<KnowledgeNote | null> {
    const readable = noteReadable('n', input.read);
    const rows = await this.#query(
      this.#read,
      `SELECT n.* FROM "${T.notes}" n WHERE n.id = ?${input.includeDeleted ? '' : ' AND n.deletedAt IS NULL'} AND ${readable.sql}`,
      [input.id, ...readable.args],
    );
    return (await this.#hydrateNotes(this.#read, rows))[0] ?? null;
  }

  async listNotes(input: {
    pageId: string;
    read: KnowledgeReadScope;
    cursor?: string;
    limit?: number;
    includeDeleted?: boolean;
  }): Promise<KnowledgeNoteListOutput> {
    const core = await loadPagesCore();
    const limit = limitOf(input.limit, core.MAX_KNOWLEDGE_PAGE_LIST_LIMIT);
    const cursor = decodeCursor(input.cursor, 2);
    const readable = noteReadable('n', input.read);
    const args: InValue[] = [input.pageId, ...readable.args];
    let after = '';
    if (cursor) {
      after = ` AND (n.createdAt > ? OR (n.createdAt = ? AND n.id > ?))`;
      args.push(cursor[0]!, cursor[0]!, cursor[1]!);
    }
    args.push(limit + 1);
    const rows = await this.#query(
      this.#read,
      `SELECT n.* FROM "${T.notes}" n WHERE n.pageId = ?${input.includeDeleted ? '' : ' AND n.deletedAt IS NULL'} AND ${readable.sql}${after} ORDER BY n.createdAt, n.id LIMIT ?`,
      args,
    );
    return this.#noteOutput(rows, limit);
  }

  async countChildScopes(input: { parentIds: string[]; read: KnowledgeReadScope }): Promise<Record<string, number>> {
    const ids = [...new Set(input.parentIds)];
    const counts: Record<string, number> = Object.fromEntries(ids.map(id => [id, 0]));
    if (ids.length === 0) return counts;
    const readable = readableScopes(input.read);
    const rows = await this.#query(
      this.#read,
      `SELECT parentId, COUNT(*) AS total FROM "${T.pages}" WHERE parentId IN (SELECT value FROM json_each(?)) AND isScope = 1 AND id IN (${readable.sql}) GROUP BY parentId`,
      [jsonList(ids), ...readable.args],
    );
    for (const row of rows) counts[String(row.parentId)] = Number(row.total);
    return counts;
  }

  async countChildPages(input: { parentIds: string[]; read: KnowledgeReadScope }): Promise<Record<string, number>> {
    const ids = [...new Set(input.parentIds)];
    const counts: Record<string, number> = Object.fromEntries(ids.map(id => [id, 0]));
    if (ids.length === 0) return counts;
    const readable = pageReadable('p', input.read);
    const rows = await this.#query(
      this.#read,
      `SELECT p.parentId AS parentId, COUNT(*) AS total FROM "${T.pages}" p WHERE p.parentId IN (SELECT value FROM json_each(?)) AND p.isScope = 0 AND p.deletedAt IS NULL AND ${readable.sql} GROUP BY p.parentId`,
      [jsonList(ids), ...readable.args],
    );
    for (const row of rows) counts[String(row.parentId)] = Number(row.total);
    return counts;
  }

  async replacePageBodyLinks(input: Parameters<KnowledgePageStore['replacePageBodyLinks']>[0]): Promise<void> {
    await this.#transaction(async tx => {
      await tx.execute({ sql: `DELETE FROM "${T.links}" WHERE fromPageId = ?`, args: [input.pageId] });
      if (input.links.length === 0) return;
      await tx.execute({
        sql: `INSERT INTO "${T.links}" (fromPageId, ref, toPageId, count) SELECT ?, json_extract(value, '$.ref'), json_extract(value, '$.toPageId'), json_extract(value, '$.count') FROM json_each(?)`,
        args: [input.pageId, JSON.stringify(input.links.map(({ ref, toPageId, count }) => ({ ref, toPageId, count })))],
      });
    });
  }

  async listPageBodyLinkSources(
    input: Parameters<KnowledgePageStore['listPageBodyLinkSources']>[0],
  ): Promise<string[]> {
    const refs = input.refs ?? [];
    const targets = input.toPageIds ?? [];
    if (refs.length === 0 && targets.length === 0) return [];
    const rows = await this.#query(
      this.#read,
      `SELECT DISTINCT fromPageId FROM "${T.links}" WHERE (toPageId IS NULL AND ref IN (SELECT value FROM json_each(?))) OR toPageId IN (SELECT value FROM json_each(?)) ORDER BY fromPageId`,
      [jsonList(refs), jsonList(targets)],
    );
    return rows.map(row => String(row.fromPageId));
  }

  /**
   * Visible links touching `ids` (from them for `out`, to them for `in`): resolved, both ends live
   * and readable, not self-links; a note link also needs a visible live note. One row per
   * (from, to, kind), counts summed.
   */
  async #links(
    read: KnowledgeReadScope,
    kinds: Parameters<KnowledgePageStore['listPageLinks']>[0]['kinds'],
    ids: string[],
    direction: 'in' | 'out' | 'both',
  ): Promise<Row[]> {
    const wanted = new Set(kinds ?? ['body', 'note']);
    const touches = (from: string, to: string): Fragment => {
      const parts: string[] = [];
      const args: InValue[] = [];
      if (direction !== 'in') {
        parts.push(`${from} IN (SELECT value FROM json_each(?))`);
        args.push(jsonList(ids));
      }
      if (direction !== 'out') {
        parts.push(`${to} IN (SELECT value FROM json_each(?))`);
        args.push(jsonList(ids));
      }
      return { sql: `(${parts.join(' OR ')})`, args };
    };
    const sources: string[] = [];
    const args: InValue[] = [];
    if (wanted.has('body')) {
      const near = touches('l.fromPageId', 'l.toPageId');
      sources.push(
        `SELECT l.fromPageId AS fromPageId, l.toPageId AS toPageId, 'body' AS kind, l.count AS count FROM "${T.links}" l WHERE l.toPageId IS NOT NULL AND ${near.sql}`,
      );
      args.push(...near.args);
    }
    if (wanted.has('note')) {
      const near = touches('n.pageId', 'm.pageId');
      const visible = noteReadable('n', read);
      sources.push(
        `SELECT n.pageId AS fromPageId, m.pageId AS toPageId, 'note' AS kind, 1 AS count FROM "${T.mentions}" m JOIN "${T.notes}" n ON n.id = m.noteId WHERE n.deletedAt IS NULL AND ${near.sql} AND ${visible.sql}`,
      );
      args.push(...near.args, ...visible.args);
    }
    if (sources.length === 0) return [];
    const fromReadable = pageReadable('fp', read);
    const toReadable = pageReadable('tp', read);
    return this.#query(
      this.#read,
      `SELECT e.fromPageId AS fromPageId, e.toPageId AS toPageId, e.kind AS kind, SUM(e.count) AS count
        FROM (${sources.join(' UNION ALL ')}) e
        JOIN "${T.pages}" fp ON fp.id = e.fromPageId AND fp.deletedAt IS NULL AND ${fromReadable.sql}
        JOIN "${T.pages}" tp ON tp.id = e.toPageId AND tp.deletedAt IS NULL AND ${toReadable.sql}
        WHERE e.fromPageId <> e.toPageId
        GROUP BY e.fromPageId, e.toPageId, e.kind
        ORDER BY e.fromPageId, e.toPageId, CASE e.kind WHEN 'body' THEN 0 ELSE 1 END`,
      [...args, ...fromReadable.args, ...toReadable.args],
    );
  }

  async countPageLinks(
    input: Parameters<KnowledgePageStore['countPageLinks']>[0],
  ): Promise<Record<string, { in: number; out: number }>> {
    const ids = [...new Set(input.pageIds)];
    const linked = new Map(ids.map(id => [id, { in: new Set<string>(), out: new Set<string>() }]));
    if (ids.length === 0) return {};
    for (const row of await this.#links(input.read, input.kinds, ids, 'both')) {
      const from = String(row.fromPageId);
      const to = String(row.toPageId);
      linked.get(from)?.out.add(to);
      linked.get(to)?.in.add(from);
    }
    return Object.fromEntries([...linked].map(([id, sets]) => [id, { in: sets.in.size, out: sets.out.size }]));
  }

  async listPageLinks(
    input: Parameters<KnowledgePageStore['listPageLinks']>[0],
  ): ReturnType<KnowledgePageStore['listPageLinks']> {
    const limit = input.limit ?? 1_000;
    if (!Number.isInteger(limit) || limit < 1) throw new RangeError('Knowledge link limit must be a positive integer');
    const ids = [...new Set(input.pageIds)];
    if (ids.length === 0) return [];
    const core = await loadPagesCore();
    const rows = await this.#links(input.read, input.kinds, ids, input.direction ?? 'both');
    return rows.slice(0, Math.min(limit, core.MAX_KNOWLEDGE_PAGE_LINKS)).map(row => ({
      fromPageId: String(row.fromPageId),
      toPageId: String(row.toPageId),
      kind: row.kind === 'note' ? 'note' : 'body',
      count: Number(row.count),
    }));
  }

  async countNotes(input: { pageIds: string[]; read: KnowledgeReadScope }): Promise<Record<string, number>> {
    const ids = [...new Set(input.pageIds)];
    const counts: Record<string, number> = Object.fromEntries(ids.map(id => [id, 0]));
    if (ids.length === 0) return counts;
    const readable = noteReadable('n', input.read);
    const rows = await this.#query(
      this.#read,
      `SELECT n.pageId AS pageId, COUNT(*) AS total FROM "${T.notes}" n WHERE n.pageId IN (SELECT value FROM json_each(?)) AND n.deletedAt IS NULL AND ${readable.sql} GROUP BY n.pageId`,
      [jsonList(ids), ...readable.args],
    );
    for (const row of rows) counts[String(row.pageId)] = Number(row.total);
    return counts;
  }

  async listNotesMentioning(input: {
    pageId: string;
    read: KnowledgeReadScope;
    cursor?: string;
    limit?: number;
  }): Promise<KnowledgeNoteListOutput> {
    const core = await loadPagesCore();
    const limit = limitOf(input.limit, core.MAX_KNOWLEDGE_PAGE_LIST_LIMIT);
    const cursor = decodeCursor(input.cursor, 2);
    const readable = noteReadable('n', input.read);
    const args: InValue[] = [input.pageId, input.pageId, ...readable.args];
    let after = '';
    if (cursor) {
      after = ` AND (n.createdAt < ? OR (n.createdAt = ? AND n.id < ?))`;
      args.push(cursor[0]!, cursor[0]!, cursor[1]!);
    }
    args.push(limit + 1);
    const rows = await this.#query(
      this.#read,
      `SELECT n.* FROM "${T.notes}" n WHERE n.pageId <> ? AND n.deletedAt IS NULL AND EXISTS (SELECT 1 FROM "${T.mentions}" m WHERE m.noteId = n.id AND m.pageId = ?) AND ${readable.sql}${after} ORDER BY n.createdAt DESC, n.id DESC LIMIT ?`,
      args,
    );
    return this.#noteOutput(rows, limit);
  }

  async #noteOutput(rows: Row[], limit: number): Promise<KnowledgeNoteListOutput> {
    const page = rows.slice(0, limit);
    return {
      notes: await this.#hydrateNotes(this.#read, page),
      ...(rows.length > limit
        ? { nextCursor: encodeCursor([String(page[page.length - 1]!.createdAt), String(page[page.length - 1]!.id)]) }
        : {}),
    };
  }

  async #assertScopes(tx: PageExecutor, ids: string[]): Promise<void> {
    if (ids.length === 0) throw new Error('A note needs at least one stamp scope');
    const found = await this.#query(
      tx,
      `SELECT id FROM "${T.pages}" WHERE isScope = 1 AND id IN (SELECT value FROM json_each(?))`,
      [jsonList(ids)],
    );
    const known = new Set(found.map(row => String(row.id)));
    const missing = ids.find(id => !known.has(id));
    if (missing) throw new Error(`Note stamp ${missing} is not a scope page`);
  }

  async addNote(input: AddKnowledgeNoteInput): Promise<KnowledgeNote> {
    await assertKnowledgeNoteTextWithinBound(input.text);
    return this.#transaction(async tx => {
      const page = await this.#livePage(tx, input.pageId);
      const stamps = [...new Set(input.stampScopeIds)];
      await this.#assertScopes(tx, stamps);
      const mentions = [...new Set(input.mentions)];
      for (const mention of mentions) await this.#livePage(tx, mention);
      const id = input.id ?? createKnowledgeUlid();
      if ((await this.#query(tx, `SELECT 1 FROM "${T.notes}" WHERE id = ?`, [id])).length > 0) {
        throw new KnowledgeConflictError(id);
      }
      const now = new Date().toISOString();
      await tx.execute({
        sql: `INSERT INTO "${T.notes}" (id, pageId, text, "when", provenance, version, createdAt, updatedAt) VALUES (?, ?, ?, ?, ?, 1, ?, ?)`,
        args: [
          id,
          input.pageId,
          input.text,
          input.when ? input.when.toISOString() : null,
          JSON.stringify(input.provenance),
          now,
          now,
        ],
      });
      for (const stamp of stamps) {
        await tx.execute({ sql: `INSERT INTO "${T.stamps}" (noteId, scopeId) VALUES (?, ?)`, args: [id, stamp] });
      }
      for (const mention of mentions) {
        await tx.execute({ sql: `INSERT INTO "${T.mentions}" (noteId, pageId) VALUES (?, ?)`, args: [id, mention] });
      }
      await this.#logActivity(
        tx,
        'note-added',
        { scopeId: String(page.scopeId), pageId: input.pageId, noteId: id, provenance: input.provenance },
        now,
      );
      return (await this.#noteById(tx, id))!;
    });
  }

  async #noteWithPage(tx: PageExecutor, id: string): Promise<{ note: Row; page: Row }> {
    const note = (await this.#query(tx, `SELECT * FROM "${T.notes}" WHERE id = ?`, [id]))[0];
    if (!note) throw new KnowledgeNotFoundError('note', id);
    const page = await this.#pageRow(tx, String(note.pageId));
    if (!page) throw new KnowledgeNotFoundError('page', String(note.pageId));
    return { note, page };
  }

  restampNote(input: {
    id: string;
    expectedVersion: number;
    stampScopeIds: string[];
    provenance: KnowledgeProvenance;
  }): Promise<KnowledgeNote> {
    return this.#transaction(async tx => {
      const { note, page } = await this.#noteWithPage(tx, input.id);
      if (note.deletedAt) throw new KnowledgeNotFoundError('note', input.id);
      if (Number(note.version) !== input.expectedVersion) throw new KnowledgeConflictError(input.id);
      const stamps = [...new Set(input.stampScopeIds)];
      await this.#assertScopes(tx, stamps);
      const now = new Date().toISOString();
      await tx.execute({ sql: `DELETE FROM "${T.stamps}" WHERE noteId = ?`, args: [input.id] });
      for (const stamp of stamps) {
        await tx.execute({ sql: `INSERT INTO "${T.stamps}" (noteId, scopeId) VALUES (?, ?)`, args: [input.id, stamp] });
      }
      await tx.execute({
        sql: `UPDATE "${T.notes}" SET version = version + 1, updatedAt = ? WHERE id = ?`,
        args: [now, input.id],
      });
      await this.#logActivity(
        tx,
        'note-restamped',
        { scopeId: String(page.scopeId), pageId: String(page.id), noteId: input.id, provenance: input.provenance },
        now,
      );
      return (await this.#noteById(tx, input.id))!;
    });
  }

  removeNote(input: { id: string; deletedBy: string; provenance: KnowledgeProvenance }): Promise<KnowledgeNote> {
    return this.#transaction(async tx => {
      const { note, page } = await this.#noteWithPage(tx, input.id);
      if (note.deletedAt) throw new KnowledgeNotFoundError('note', input.id);
      const now = new Date().toISOString();
      await tx.execute({
        sql: `UPDATE "${T.notes}" SET deletedAt = ?, deletedBy = ?, version = version + 1, updatedAt = ? WHERE id = ?`,
        args: [now, input.deletedBy, now, input.id],
      });
      await this.#logActivity(
        tx,
        'note-removed',
        { scopeId: String(page.scopeId), pageId: String(page.id), noteId: input.id, provenance: input.provenance },
        now,
      );
      return (await this.#noteById(tx, input.id))!;
    });
  }

  restoreNote(input: { id: string; provenance: KnowledgeProvenance }): Promise<KnowledgeNote> {
    return this.#transaction(async tx => {
      const { note, page } = await this.#noteWithPage(tx, input.id);
      if (!note.deletedAt) throw new KnowledgeNotFoundError('note', input.id);
      const now = new Date().toISOString();
      await tx.execute({
        sql: `UPDATE "${T.notes}" SET deletedAt = NULL, deletedBy = NULL, version = version + 1, updatedAt = ? WHERE id = ?`,
        args: [now, input.id],
      });
      await this.#logActivity(
        tx,
        'note-restored',
        { scopeId: String(page.scopeId), pageId: String(page.id), noteId: input.id, provenance: input.provenance },
        now,
      );
      return (await this.#noteById(tx, input.id))!;
    });
  }

  // Search and activity

  async searchPages(input: SearchKnowledgePagesInput): Promise<KnowledgePageSearchHit[]> {
    const words = knowledgeSearchWords(input.query);
    if (!words.length) return [];
    const phrase = input.query.trim().toLowerCase().replace(/\s+/g, ' ');
    const limit = Math.max(1, input.limit ?? 20);
    const likes = words.map(word => `%${escapeLike(word)}%`);
    const readable = pageReadable('p', input.read);
    const scopeFilter = input.scopeIds ? ` AND p.scopeId IN (SELECT value FROM json_each(?))` : '';
    const scopeArgs: InValue[] = input.scopeIds ? [jsonList(input.scopeIds)] : [];
    const field = (column: string) => `lower(COALESCE(${column}, '')) LIKE ? ESCAPE '='`;
    const pageMatch = words
      .map(() => `(${field('p.name')} OR ${field('p.description')} OR ${field('p.body')})`)
      .join(' OR ');
    const pageScore = words
      .map(
        () =>
          `(CASE WHEN ${field('p.name')} THEN ${KNOWLEDGE_SEARCH_WEIGHTS.name} WHEN ${field('p.description')} THEN ${KNOWLEDGE_SEARCH_WEIGHTS.description} WHEN ${field('p.body')} THEN ${KNOWLEDGE_SEARCH_WEIGHTS.body} ELSE 0 END)`,
      )
      .join(' + ');
    const pageCount = words
      .map(() => `(CASE WHEN ${field('p.name')} OR ${field('p.description')} OR ${field('p.body')} THEN 1 ELSE 0 END)`)
      .join(' + ');
    const triple = likes.flatMap(like => [like, like, like]);
    const pageRows = await this.#query(
      this.#read,
      `SELECT p.* FROM "${T.pages}" p WHERE p.deletedAt IS NULL AND p.isScope = 0 AND ${readable.sql}${scopeFilter} AND (${pageMatch}) ORDER BY CASE WHEN instr(p.canonicalName, ?) > 0 THEN 0 ELSE 1 END, (${pageCount}) DESC, (${pageScore}) DESC, p.updatedAt DESC, p.id ASC LIMIT ?`,
      [...readable.args, ...scopeArgs, ...triple, phrase, ...triple, ...triple, limit],
    );
    const hits: KnowledgePageSearchHit[] = pageRows.map(row => ({ type: 'page', page: toPage(row) }));
    if (hits.length >= limit) return hits;
    const noteVisible = noteReadable('n', input.read);
    const noteHas = words.map(() => `lower(n.text) LIKE ? ESCAPE '='`);
    const noteRows = await this.#query(
      this.#read,
      `SELECT n.* FROM "${T.notes}" n JOIN "${T.pages}" p ON p.id = n.pageId WHERE n.deletedAt IS NULL AND p.deletedAt IS NULL${scopeFilter} AND (${noteHas.join(' OR ')}) AND ${noteVisible.sql} ORDER BY (${noteHas.map(has => `(CASE WHEN ${has} THEN 1 ELSE 0 END)`).join(' + ')}) DESC, n.updatedAt DESC, n.id DESC LIMIT ?`,
      [...scopeArgs, ...likes, ...noteVisible.args, ...likes, limit - hits.length],
    );
    const notes = await this.#hydrateNotes(this.#read, noteRows);
    for (const note of notes) {
      const page = await this.#pageRow(this.#read, note.pageId);
      if (page) hits.push({ type: 'note', note, page: toPage(page) });
    }
    return hits;
  }

  async listPageActivity(input: {
    read: KnowledgeReadScope;
    scopeId?: string;
    pageId?: string;
    cursor?: string;
    limit?: number;
  }): Promise<{ events: KnowledgePageActivityEvent[]; nextCursor?: string }> {
    const core = await loadPagesCore();
    const limit = limitOf(input.limit, core.MAX_KNOWLEDGE_PAGE_LIST_LIMIT);
    const cursor = decodeCursor(input.cursor, 1);
    const readable = pageReadable('p', input.read);
    const noteVisible = noteReadable('n', input.read);
    const args: InValue[] = [...readable.args];
    let filters = '';
    if (input.scopeId !== undefined) {
      filters += ` AND p.scopeId = ?`;
      args.push(input.scopeId);
    }
    if (input.pageId !== undefined) {
      filters += ` AND e.pageId = ?`;
      args.push(input.pageId);
    }
    if (cursor) {
      filters += ` AND e.id < ?`;
      args.push(cursor[0]!);
    }
    args.push(...noteVisible.args, limit + 1);
    const rows = await this.#query(
      this.#read,
      `SELECT e.* FROM "${T.activity}" e JOIN "${T.pages}" p ON p.id = e.pageId WHERE ${readable.sql}${filters} AND (e.noteId IS NULL OR EXISTS (SELECT 1 FROM "${T.notes}" n WHERE n.id = e.noteId AND ${noteVisible.sql})) ORDER BY e.id DESC LIMIT ?`,
      args,
    );
    const page = rows.slice(0, limit);
    return {
      events: page.map(row => ({
        id: String(row.id),
        action: String(row.action) as KnowledgePageActivityAction,
        scopeId: String(row.scopeId),
        pageId: String(row.pageId),
        ...(row.noteId ? { noteId: String(row.noteId) } : {}),
        provenance: provenance(row.provenance),
        createdAt: new Date(String(row.createdAt)),
      })),
      ...(rows.length > limit ? { nextCursor: encodeCursor([String(page[page.length - 1]!.id)]) } : {}),
    };
  }

  /** Rewrites the audience index rows of one pin to match `audience`. */
  async #indexAudience(tx: PageExecutor, pinId: string, audience: string[]): Promise<void> {
    await tx.execute({ sql: `DELETE FROM "${T.pinAudiences}" WHERE pinId = ?`, args: [pinId] });
    for (const entry of audience) {
      await tx.execute({
        sql: `INSERT OR IGNORE INTO "${T.pinAudiences}" (pinId, audience) VALUES (?, ?)`,
        args: [pinId, entry],
      });
    }
  }

  // Pins

  addPinAudience(input: Parameters<KnowledgePageStore['addPinAudience']>[0]): Promise<KnowledgePin> {
    const kind = input.kind ?? 'page';
    const depth = kind === 'list' ? (input.depth ?? 1) : null;
    return this.#transaction(async tx => {
      const page = await this.#livePage(tx, input.pageId);
      const now = new Date().toISOString();
      const existing = (
        await this.#query(tx, `SELECT * FROM "${T.pins}" WHERE pageId = ? AND kind = ?`, [input.pageId, kind])
      )[0];
      if (!existing) {
        const id = createKnowledgeUlid();
        await tx.execute({
          sql: `INSERT INTO "${T.pins}" (id, pageId, kind, depth, audience, createdBy, createdAt, updatedAt) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
          args: [
            id,
            input.pageId,
            kind,
            depth,
            JSON.stringify([...new Set(input.audience)]),
            input.createdBy,
            now,
            now,
          ],
        });
        await this.#indexAudience(tx, id, [...new Set(input.audience)]);
        await this.#logActivity(
          tx,
          'pin-added',
          { scopeId: String(page.scopeId), pageId: input.pageId, provenance: { author: input.createdBy } },
          now,
        );
        return toPin((await this.#query(tx, `SELECT * FROM "${T.pins}" WHERE id = ?`, [id]))[0]!);
      }
      const current = JSON.parse(String(existing.audience)) as string[];
      const merged = [...new Set([...current, ...input.audience])];
      const depthChanged = (existing.depth === null ? null : Number(existing.depth)) !== depth;
      if (merged.length !== current.length || depthChanged) {
        await tx.execute({
          sql: `UPDATE "${T.pins}" SET audience = ?, depth = ?, updatedAt = ? WHERE id = ?`,
          args: [JSON.stringify(merged), depth, now, String(existing.id)],
        });
        await this.#indexAudience(tx, String(existing.id), merged);
        await this.#logActivity(
          tx,
          'pin-added',
          { scopeId: String(page.scopeId), pageId: input.pageId, provenance: { author: input.createdBy } },
          now,
        );
      }
      return toPin((await this.#query(tx, `SELECT * FROM "${T.pins}" WHERE id = ?`, [String(existing.id)]))[0]!);
    });
  }

  removePinAudience(input: Parameters<KnowledgePageStore['removePinAudience']>[0]): Promise<KnowledgePin | null> {
    return this.#transaction(async tx => {
      const existing = (
        await this.#query(tx, `SELECT * FROM "${T.pins}" WHERE pageId = ? AND kind = ?`, [
          input.pageId,
          input.kind ?? 'page',
        ])
      )[0];
      if (!existing) return null;
      const current = JSON.parse(String(existing.audience)) as string[];
      const remove = new Set(input.audience);
      const remaining = current.filter(entry => !remove.has(entry));
      if (remaining.length === current.length) return toPin(existing);
      const page = await this.#pageRow(tx, input.pageId);
      const now = new Date().toISOString();
      if (page) {
        await this.#logActivity(
          tx,
          'pin-removed',
          { scopeId: String(page.scopeId), pageId: input.pageId, provenance: { author: input.removedBy } },
          now,
        );
      }
      if (remaining.length === 0) {
        await this.#indexAudience(tx, String(existing.id), []);
        await tx.execute({ sql: `DELETE FROM "${T.pins}" WHERE id = ?`, args: [String(existing.id)] });
        return null;
      }
      await tx.execute({
        sql: `UPDATE "${T.pins}" SET audience = ?, updatedAt = ? WHERE id = ?`,
        args: [JSON.stringify(remaining), now, String(existing.id)],
      });
      await this.#indexAudience(tx, String(existing.id), remaining);
      return toPin((await this.#query(tx, `SELECT * FROM "${T.pins}" WHERE id = ?`, [String(existing.id)]))[0]!);
    });
  }

  async listPins(input: {
    audience: string[] | 'all';
    read: KnowledgeReadScope;
    kind?: KnowledgePinKind;
    pageIds?: string[];
    excludePageIds?: string[];
    withBody?: boolean;
    count?: boolean;
    cursor?: string;
    limit?: number;
  }): Promise<{ pins: KnowledgeListedPin[]; nextCursor?: string; total?: number }> {
    const core = await loadPagesCore();
    const limit = limitOf(input.limit, core.MAX_KNOWLEDGE_PAGE_LIST_LIMIT);
    const cursor = decodeCursor(input.cursor, 2);
    const readable = pageReadable('p', input.read);
    const args: InValue[] = [...readable.args];
    let filters = '';
    if (input.audience !== 'all') {
      filters += ` AND pin.id IN (SELECT pa.pinId FROM json_each(?) a JOIN "${T.pinAudiences}" pa ON pa.audience = a.value)`;
      args.push(jsonList(input.audience));
    }
    if (input.kind) {
      filters += ` AND pin.kind = ?`;
      args.push(input.kind);
    }
    if (input.pageIds) {
      filters += ` AND pin.pageId IN (SELECT value FROM json_each(?))`;
      args.push(jsonList(input.pageIds));
    }
    if (input.excludePageIds?.length) {
      filters += ` AND (pin.kind <> 'page' OR pin.pageId NOT IN (SELECT value FROM json_each(?)))`;
      args.push(jsonList(input.excludePageIds));
    }
    if (input.withBody) {
      filters += ` AND (pin.kind <> 'page' OR (p.body IS NOT NULL AND trim(p.body, char(32, 9, 10, 11, 12, 13)) <> ''))`;
    }
    const from = `FROM "${T.pins}" pin JOIN "${T.pages}" p ON p.id = pin.pageId WHERE p.deletedAt IS NULL AND ${readable.sql}${filters}`;
    let total: number | undefined;
    if (input.count) {
      total = Number((await this.#query(this.#read, `SELECT COUNT(*) AS n ${from}`, args))[0]!.n);
    }
    const pageArgs = [...args];
    let cursorFilter = '';
    if (cursor) {
      cursorFilter = ` AND (pin.createdAt < ? OR (pin.createdAt = ? AND pin.id < ?))`;
      pageArgs.push(cursor[0]!, cursor[0]!, cursor[1]!);
    }
    pageArgs.push(limit + 1);
    const rows = await this.#query(
      this.#read,
      `SELECT pin.*, p.name AS pageName ${from}${cursorFilter} ORDER BY pin.createdAt DESC, pin.id DESC LIMIT ?`,
      pageArgs,
    );
    const page = rows.slice(0, limit);
    return {
      pins: page.map(toListedPin),
      ...(rows.length > limit
        ? { nextCursor: encodeCursor([String(page[page.length - 1]!.createdAt), String(page[page.length - 1]!.id)]) }
        : {}),
      ...(total === undefined ? {} : { total }),
    };
  }
}
